{
  "name": "@path-app/web",
  "private": true,
  "version": "0.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "tsc --noEmit && vite build",
    "typecheck": "tsc --noEmit",
    "preview": "vite preview"
  },
  "dependencies": {
    "@react-three/drei": "^10.7.9",
    "@react-three/fiber": "^9.8.2",
    "lucide-react": "^1.70.0",
    "qrcode.react": "^4.2.0",
    "react": "^19.3.1",
    "react-dom": "^19.3.1",
    "react-router": "^8.5.1",
    "sonner": "^2.0.8",
    "three": "^0.187.0"
  },
  "devDependencies": {
    "@tailwindcss/vite": "^4.3.5",
    "@types/react": "^19.3.0",
    "@types/react-dom": "^19.3.0",
    "@types/three": "^0.187.0",
    "@vitejs/plugin-react": "^6.2.1",
    "axe-core": "^4.14.0",
    "tailwindcss": "^4.3.5",
    "typescript": "^7.0.2",
    "vite": "^8.3.6"
  }
}
import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { createBrowserRouter, Navigate } from "react-router";
import { RouterProvider } from "react-router/dom";
import "./index.css";
import AppLayout from "./components/AppLayout";
import { PreferencesProvider } from "./lib/preferences";
import Community from "./routes/Community";
import Home from "./routes/Home";
import ManageMap from "./routes/ManageMap";
import MyMaps from "./routes/MyMaps";
import GuestView from "./routes/GuestView";
import NotFound from "./routes/NotFound";
import Settings from "./routes/Settings";
import Upload from "./routes/Upload";

const router = createBrowserRouter([
  { path: "/", element: <Home /> },
  {
    element: <AppLayout />,
    children: [
      { path: "/maps", element: <MyMaps /> },
      { path: "/maps/new", element: <Upload /> },
      { path: "/maps/:shareId", element: <ManageMap /> },
      { path: "/community", element: <Community /> },
      { path: "/settings", element: <Settings /> },
    ],
  },
  { path: "/upload", element: <Navigate to="/maps/new" replace /> },
  { path: "/s/:shareId", element: <GuestView /> },
  { path: "*", element: <NotFound /> },
]);

const root = document.getElementById("root");
if (!root) throw new Error("Missing #root element");

createRoot(root).render(
  <StrictMode>
    <PreferencesProvider>
      <RouterProvider router={router} />
    </PreferencesProvider>
  </StrictMode>,
);
@import "tailwindcss";

/* Applies when the person picks "Extra large" text in Settings. */
@custom-variant xl-text (&:where([data-text-size="xlarge"] *));

/*
 * Design tokens from apps/web/DESIGN.md.
 * Contrast rules: coral is a fill only (route, pins, CTA background) — never text,
 * never white-on-coral. Coral buttons use `ink` text. Coral-flavored text uses `rust`.
 * Every 3D view sits on `night`.
 */
@theme {
  --color-paper: #f3ebd0;
  --color-surface: #faf5e6;
  --color-forest: #2f4a3a;
  --color-coral: #f48057;
  --color-rust: #a8421f;
  --color-night: #121c16;
  --color-sage: #a9c4ae;
  --color-ink: #15221b;
  --color-muted: #5e6b60;

  --font-display: "Overpass", ui-sans-serif, system-ui, sans-serif;
  --font-sans: "Atkinson Hyperlegible Next", ui-sans-serif, system-ui, sans-serif;
  --font-mono: "Atkinson Hyperlegible Mono", ui-monospace, "SFMono-Regular", monospace;
}

@layer base {
  html {
    -webkit-text-size-adjust: 100%;
  }

  body {
    @apply bg-paper font-sans text-forest antialiased;
  }

  /*
   * Focus ring for keyboard users. It must reach 3:1 against what's behind it, and
   * coral on cream is only 2.2:1, so the color follows the surface:
   * forest on paper (8.1:1), paper on the forest menu (8.1:1), coral on night (6.7:1).
   */
  :root {
    --focus-ring: var(--color-forest);
  }
  [data-surface="forest"] {
    --focus-ring: var(--color-paper);
  }
  [data-surface="night"] {
    --focus-ring: var(--color-coral);
  }
  [data-surface="light"] {
    --focus-ring: var(--color-forest);
  }

  :focus-visible {
    outline: 3px solid var(--focus-ring);
    outline-offset: 2px;
  }
}

/*
 * Reduced motion: on when the person picks "Reduce motion" in Settings, or when they
 * keep "Match my device" and the device asks for it. "Allow motion" overrides the device.
 */
@media (prefers-reduced-motion: reduce) {
  :root:not([data-motion="full"]) *,
  :root:not([data-motion="full"]) *::before,
  :root:not([data-motion="full"]) *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

:root[data-motion="reduce"] *,
:root[data-motion="reduce"] *::before,
:root[data-motion="reduce"] *::after {
  animation-duration: 0.01ms !important;
  animation-iteration-count: 1 !important;
  transition-duration: 0.01ms !important;
  scroll-behavior: auto !important;
}
import { createContext, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from "react";

/**
 * Accessibility and comfort settings, kept on this device (no account needed, so
 * guests can use them too). Saved with localStorage. If storage is blocked
 * (private browsing), the settings still work for this visit.
 */
export type TextSize = "default" | "large" | "xlarge";
export type MotionPreference = "system" | "reduce" | "full";

export interface Preferences {
  textSize: TextSize;
  motion: MotionPreference;
  /** Default for the per-trip "Avoid stairs" switch on a map. */
  avoidStairs: boolean;
}

export const DEFAULT_PREFERENCES: Preferences = { textSize: "default", motion: "system", avoidStairs: false };

const STORAGE_KEY = "path.preferences.v1";

/** Root font size for each text size. Everything is sized in rem, so the whole UI scales. */
export const TEXT_SCALE: Record<TextSize, string> = { default: "100%", large: "118.75%", xlarge: "137.5%" };

function load(): Preferences {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return DEFAULT_PREFERENCES;
    const saved = JSON.parse(raw) as Partial<Preferences>;
    return {
      textSize: saved.textSize && saved.textSize in TEXT_SCALE ? saved.textSize : DEFAULT_PREFERENCES.textSize,
      motion: saved.motion === "reduce" || saved.motion === "full" ? saved.motion : "system",
      avoidStairs: saved.avoidStairs === true,
    };
  } catch {
    return DEFAULT_PREFERENCES;
  }
}

function save(preferences: Preferences) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(preferences));
  } catch {
    // Storage unavailable: keep the in-memory value for this visit.
  }
}

/** Puts the settings on <html> so CSS can react: font size and data-motion. */
function apply(preferences: Preferences) {
  const root = document.documentElement;
  root.style.fontSize = TEXT_SCALE[preferences.textSize];
  root.dataset.textSize = preferences.textSize;
  root.dataset.motion = preferences.motion;
}

interface PreferencesContext {
  preferences: Preferences;
  update: (change: Partial<Preferences>) => void;
}

const Context = createContext<PreferencesContext | null>(null);

export function PreferencesProvider({ children }: { children: ReactNode }) {
  const [preferences, setPreferences] = useState<Preferences>(load);

  useEffect(() => apply(preferences), [preferences]);

  // Another tab changed the settings: follow it.
  useEffect(() => {
    const onStorage = (event: StorageEvent) => {
      if (event.key === STORAGE_KEY) setPreferences(load());
    };
    window.addEventListener("storage", onStorage);
    return () => window.removeEventListener("storage", onStorage);
  }, []);

  const update = useCallback((change: Partial<Preferences>) => {
    setPreferences((current) => {
      const next = { ...current, ...change };
      save(next);
      return next;
    });
  }, []);

  const value = useMemo(() => ({ preferences, update }), [preferences, update]);
  return <Context.Provider value={value}>{children}</Context.Provider>;
}

export function usePreferences(): PreferencesContext {
  const value = useContext(Context);
  if (!value) throw new Error("usePreferences must be used inside PreferencesProvider");
  return value;
}

/** True when motion should be reduced: the user chose it, or chose "match my device" and the device asks for it. */
export function useReducedMotion(): boolean {
  const { preferences } = usePreferences();
  const [systemReduce, setSystemReduce] = useState(
    () => typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches,
  );
  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const onChange = () => setSystemReduce(query.matches);
    query.addEventListener("change", onChange);
    return () => query.removeEventListener("change", onChange);
  }, []);
  if (preferences.motion === "reduce") return true;
  if (preferences.motion === "full") return false;
  return systemReduce;
}

/**
 * The "Avoid stairs" choice for one trip on one map. It starts from the saved default
 * and changing it doesn't touch the default, so someone walking with a friend who uses
 * a wheelchair (or who is just tired) can switch it on for this trip only. It lasts
 * for this browser tab, so a reload keeps the choice.
 */
export function useTripAvoidStairs(shareId: string): [boolean, (value: boolean) => void] {
  const { preferences } = usePreferences();
  const key = `path.trip.avoidStairs.${shareId}`;

