<script>
(function () {
  const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  /* ---------- procedural point cloud of the fixture's T corridor ---------- */
  let seed = 11;
  const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
  const pts = [];
  const add = (x, y, z, c, j) => {
    j = j == null ? 22 : j;
    const r = Math.max(0, Math.min(255, c[0] + (rnd() - .5) * j));
    const g = Math.max(0, Math.min(255, c[1] + (rnd() - .5) * j));
    const b = Math.max(0, Math.min(255, c[2] + (rnd() - .5) * j));
    pts.push({ x, y, z, col: "rgb(" + (r|0) + "," + (g|0) + "," + (b|0) + ")" });
  };
  const floorC = [150, 146, 132], wallC = [206, 199, 180];
  for (let i = 0; i < 900; i++) add(-1 + rnd() * 2, 0, 0.6 - rnd() * 3.6, floorC);
  for (let i = 0; i < 1400; i++) add(-4.5 + rnd() * 9, 0, -3 - rnd() * 2, floorC);
  const inDoor = (x, y) => y < 2.1 && (Math.abs(x + 3) < .55 || Math.abs(x - 3) < .55);
  const wall = (n, f) => { for (let i = 0; i < n; i++) { const p = f(rnd()), y = rnd() * 2.6; if (p[2] === -5 && inDoor(p[0], y)) continue; add(p[0], y, p[1], wallC); } };
  wall(380, u => [-1, 0.6 - u * 3.6]);
  wall(380, u => [1, 0.6 - u * 3.6]);
  wall(900, u => [-4.5 + u * 9, -5, -5]);
  wall(300, u => [-4.5 + u * 3.5, -3]);
  wall(300, u => [1 + u * 3.5, -3]);
  wall(170, u => [-4.5, -3 - u * 2]);
  wall(170, u => [4.5, -3 - u * 2]);
  const door = (cx, c) => { for (let i = 0; i < 280; i++) add(cx - .55 + rnd() * 1.1, rnd() * 2.1, -4.97, c, 30); };
  door(-3, [230, 170, 60]);
  door(3, [150, 100, 200]);
  for (let i = 0; i < 170; i++) add(-.7 + rnd() * 1.4, .01, .6 - rnd() * .7, [70, 165, 105], 26);
  pts.forEach(p => {
    const a = rnd() * Math.PI * 2, b = (rnd() - .5) * Math.PI, r = 6 + rnd() * 8;
    p.sx = Math.cos(a) * Math.cos(b) * r; p.sy = 1 + Math.sin(b) * r * .6; p.sz = -2.5 + Math.sin(a) * Math.cos(b) * r;
    p.delay = rnd() * .55 + (2.6 - p.y) * .05;
  });

  const WP = { entrance: [0, 0, 0], junction: [0, 0, -4], workshop: [-3, 0, -4], booth: [3, 0, -4] };
  const ROUTES = { workshop: ["entrance", "junction", "workshop"], booth: ["entrance", "junction", "booth"] };
  const CUES = { workshop: "Turn left at the amber doorway", booth: "Turn right at the purple doorway" };

  function Scene(canvas, opts) {
    const ctx = canvas.getContext("2d");
    let w = 0, h = 0, dpr = 1;
    let dest = opts.dest || "workshop";
    let t0 = performance.now(), routeT0 = t0 + (reduce ? 0 : 2300);
    let userYaw = 0, userPitch = 0, dragging = false, lx = 0, ly = 0, visible = true, raf = 0;
    const s = this;

    function resize() {
      const r = canvas.getBoundingClientRect();
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      w = r.width; h = r.height;
      canvas.width = Math.max(1, w * dpr); canvas.height = Math.max(1, h * dpr);
    }
    new ResizeObserver(resize).observe(canvas);
    resize();

    canvas.addEventListener("pointerdown", e => { dragging = true; lx = e.clientX; ly = e.clientY; canvas.setPointerCapture(e.pointerId); });
    canvas.addEventListener("pointermove", e => {
      if (!dragging) return;
      userYaw += (e.clientX - lx) * .008; userPitch = Math.max(-.45, Math.min(.5, userPitch + (e.clientY - ly) * .004));
      lx = e.clientX; ly = e.clientY;
    });
    const end = () => { dragging = false; };
    canvas.addEventListener("pointerup", end); canvas.addEventListener("pointercancel", end);

    new IntersectionObserver(es => { visible = es[0].isIntersecting; if (visible && !raf) raf = requestAnimationFrame(frame); }).observe(canvas);

    const ease = x => 1 - Math.pow(1 - x, 3);

    function frame(now) {
      raf = 0;
      if (!visible) return;
      draw(now);
      raf = requestAnimationFrame(frame);
    }

    function draw(now) {
      const T = (now - t0) / 1000;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      const yaw = (opts.yaw || .42) + userYaw + (reduce ? 0 : Math.sin(T * .18) * .22);
      const pitch = (opts.pitch || .66) + userPitch;
      const cyw = Math.cos(yaw), syw = Math.sin(yaw), cp = Math.cos(pitch), sp = Math.sin(pitch);
      const tx = 0, ty = .7, tz = -2.4, D = opts.dist || 10.5;
      const focal = Math.min(w * .95, h * 1.25) * (opts.zoom || 1);
      const cx = w / 2, cy = h * (opts.cy || .5);
      const proj = (x, y, z) => {
        x -= tx; y -= ty; z -= tz;
        const x1 = cyw * x - syw * z, z1 = syw * x + cyw * z;
        const y2 = cp * y - sp * z1, z2 = sp * y + cp * z1;
        const depth = D - z2, f = focal / depth;
        return [cx + x1 * f, cy - y2 * f, depth, f];
      };
      // points
      const asm = reduce ? 1 : Math.min(1, T / 2.2);
      for (let i = 0; i < pts.length; i++) {
        const p = pts[i];
        let k = reduce ? 1 : Math.max(0, Math.min(1, (asm * 1.6 - p.delay)));
        k = ease(k);
        const x = p.sx + (p.x - p.sx) * k, y = p.sy + (p.y - p.sy) * k, z = p.sz + (p.z - p.sz) * k;
        const q = proj(x, y, z);
        if (q[2] <= .3) continue;
        const sz = Math.max(1, q[3] * .03);
        ctx.globalAlpha = Math.max(.25, Math.min(1, 1.35 - q[2] / 16)) * (.35 + .65 * k);
        ctx.fillStyle = p.col;
        ctx.fillRect(q[0] - sz / 2, q[1] - sz / 2, sz, sz);
      }
      ctx.globalAlpha = 1;

      // route
      const ids = ROUTES[dest];
      const segs = []; let total = 0;
      for (let i = 0; i < ids.length - 1; i++) {
        const a = WP[ids[i]], b = WP[ids[i + 1]];
        const len = Math.hypot(b[0] - a[0], b[2] - a[2]);
        segs.push({ a, b, len, start: total }); total += len;
      }
      const rp = reduce ? 1 : Math.max(0, Math.min(1, (now - routeT0) / 2600));
      const dist = ease(rp) * total;
      const at = d => {
        for (const sg of segs) if (d <= sg.start + sg.len + 1e-6) {
          const u = (d - sg.start) / sg.len;
          return { p: [sg.a[0] + (sg.b[0] - sg.a[0]) * u, .03, sg.a[2] + (sg.b[2] - sg.a[2]) * u], dir: [(sg.b[0] - sg.a[0]) / sg.len, (sg.b[2] - sg.a[2]) / sg.len] };
        }
        const l = segs[segs.length - 1]; return { p: [l.b[0], .03, l.b[2]], dir: [(l.b[0] - l.a[0]) / l.len, (l.b[2] - l.a[2]) / l.len] };
      };

      // start pulse
      const s0 = proj(0, .02, 0);
      const pulse = reduce ? .5 : (T * .8) % 1;
      ctx.strokeStyle = "rgba(120,210,150," + (1 - pulse) + ")"; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.ellipse(s0[0], s0[1], s0[3] * (.2 + pulse * .5), s0[3] * (.2 + pulse * .5) * Math.max(.2, sp), 0, 0, Math.PI * 2); ctx.stroke();

      if (dist > 0) {
        ctx.lineCap = "round"; ctx.lineJoin = "round";
        ctx.beginPath();
        const steps = Math.max(2, Math.ceil(dist / .1));
        for (let i = 0; i <= steps; i++) { const q = at(dist * i / steps).p, r = proj(q[0], q[1], q[2]); i ? ctx.lineTo(r[0], r[1]) : ctx.moveTo(r[0], r[1]); }
        ctx.strokeStyle = "rgba(244,128,87,.28)"; ctx.lineWidth = 10; ctx.stroke();
        ctx.strokeStyle = "#F48057"; ctx.lineWidth = 3.5; ctx.stroke();

        // footprints
        if (opts.prints !== false) {
          const stride = .42;
          for (let d = .3, n = 0; d < dist; d += stride, n++) {
            const a = at(d), side = n % 2 ? 1 : -1;
            const nx = -a.dir[1], nz = a.dir[0];
            const px = a.p[0] + nx * side * .13, pz = a.p[2] + nz * side * .13;
            const c = proj(px, .04, pz), c2 = proj(px + a.dir[0] * .2, .04, pz + a.dir[1] * .2);
            const ang = Math.atan2(c2[1] - c[1], c2[0] - c[0]);
            const age = (dist - d);
            ctx.save(); ctx.translate(c[0], c[1]); ctx.rotate(ang);
            ctx.globalAlpha = Math.max(.25, 1 - age / 5);
            ctx.fillStyle = "#F3EBD0";
            const L = c[3] * .12, W = c[3] * .045;
            ctx.beginPath(); ctx.ellipse(L * .15, 0, L * .55, W, 0, 0, Math.PI * 2); ctx.fill();
            ctx.beginPath(); ctx.ellipse(-L * .55, 0, L * .28, W * .8, 0, 0, Math.PI * 2); ctx.fill();
            ctx.restore();
          }
          ctx.globalAlpha = 1;
        }
      }
      // destination pin
      const dp = WP[ROUTES[dest][2]];
      const base = proj(dp[0], 0, dp[2]), top = proj(dp[0], 1.1, dp[2]);
      const pinA = reduce ? 1 : Math.max(0, Math.min(1, (rp - .7) / .3));
      if (pinA > 0) {
        ctx.globalAlpha = pinA;
        ctx.strokeStyle = "#F48057"; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(base[0], base[1]); ctx.lineTo(top[0], top[1]); ctx.stroke();
        ctx.fillStyle = "#F48057"; ctx.beginPath(); ctx.arc(top[0], top[1], Math.max(5, top[3] * .14), 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#121C16"; ctx.beginPath(); ctx.arc(top[0], top[1], Math.max(2, top[3] * .055), 0, Math.PI * 2); ctx.fill();
        ctx.globalAlpha = 1;
      }
      if (opts.onProgress) opts.onProgress(rp, dist, total, dest);
    }

    s.setDest = d => { dest = d; routeT0 = performance.now(); if (reduce && !raf) raf = requestAnimationFrame(frame); };
    s.replay = () => { t0 = performance.now(); routeT0 = t0 + (reduce ? 0 : 2300); };
    raf = requestAnimationFrame(frame);
  }

  /* hero */
  const readout = document.getElementById("heroReadout");
  const hero = new Scene(document.getElementById("heroCanvas"), {
    dest: "workshop", zoom: 1, cy: .56,
    onProgress: (rp, dist, total, d) => {
      const txt = rp < 1 ? "walking… " + dist.toFixed(1) + " / " + total.toFixed(1) + " m" : (d === "workshop" ? "workshop (−3.0, 0.0, −4.0) m" : "booth (3.0, 0.0, −4.0) m") + " · " + total.toFixed(1) + " m";
      if (readout.textContent !== txt) readout.textContent = txt;
    }
  });
  document.getElementById("replay").addEventListener("click", () => hero.replay());
  document.querySelectorAll("[data-dest]").forEach(b => b.addEventListener("click", () => {
    document.querySelectorAll("[data-dest]").forEach(x => x.setAttribute("aria-pressed", String(x === b)));
    hero.setDest(b.dataset.dest);
  }));
