}
import tailwindcss from "@tailwindcss/vite";
import react from "@vitejs/plugin-react";
import { defineConfig } from "vite";

// The local scan mock (tools/scan_mock.py) listens on IPv4 loopback only,
// so target 127.0.0.1 rather than "localhost" (which Node may resolve to ::1).
const API_TARGET = "http://127.0.0.1:8001";

const proxy = {
  "/api": { target: API_TARGET, changeOrigin: false },
};

export default defineConfig({
  plugins: [react(), tailwindcss()],
  server: { port: 5173, proxy },
  preview: { port: 4173, proxy },
});
/// <reference types="vite/client" />

interface ImportMetaEnv {
  /** Account the local scan mock treats as signed in for owner actions such as upload and sharing (dev only). */
  readonly VITE_DEV_USER?: string;
  /** Name shown for that stand-in account in the app menu (dev only). */
  readonly VITE_DEV_NAME?: string;
}

interface ImportMeta {
  readonly env: ImportMetaEnv;
}
function Framing({ scan, resetToken }: { scan: PointScan; resetToken: number }) {
  const camera = useThree((s) => s.camera);
  const controls = useThree((s) => s.controls) as unknown as OrbitLike | null;

  useEffect(() => {
    const { center, radius } = scan.bounds;
    // Fit the bounding sphere on narrow (portrait phone) screens too: use the
    // smaller of the vertical and horizontal fields of view.
    const perspective = camera as typeof camera & { fov?: number; aspect?: number };
    const vFov = MathUtils.degToRad(perspective.fov ?? 55);
    const hFov = 2 * Math.atan(Math.tan(vFov / 2) * (perspective.aspect ?? 1));
    const distance = (radius / Math.sin(Math.min(vFov, hFov) / 2)) * 0.85;
    // About 24° above the floor, behind the entrance: low enough to read doorways as
    // standing shapes, high enough to see the corridor layout.
    camera.position.set(center.x, center.y + distance * 0.4, center.z + distance * 0.92);
    camera.near = Math.max(radius / 1000, 0.001);
    camera.far = radius * 50;
    camera.updateProjectionMatrix();
    if (controls) {
      controls.target.copy(center);
      controls.minDistance = radius * 0.05;
      controls.maxDistance = radius * 6;
      controls.update();
    } else {
      camera.lookAt(center);
    }
  }, [scan, camera, controls, resetToken]);

  return null;
}

/**
 * Keyboard control for people who can't drag or pinch. While the map has focus:
 * arrow keys turn it (Shift for bigger steps), + and − zoom, R resets the view.
 */
function KeyboardOrbit({ target, onReset }: { target: RefObject<HTMLDivElement | null>; onReset: () => void }) {
  const camera = useThree((s) => s.camera);
  const controls = useThree((s) => s.controls) as unknown as OrbitLike | null;

  useEffect(() => {
    const element = target.current;
    if (!element || !controls) return;
    const onKey = (event: KeyboardEvent) => {
      if (event.altKey || event.ctrlKey || event.metaKey) return;
      if (event.key === "r" || event.key === "R") {
        event.preventDefault();
        onReset();
        return;
      }
      const step = MathUtils.degToRad(event.shiftKey ? 30 : 10);
      const spherical = new Spherical().setFromVector3(camera.position.clone().sub(controls.target));
      switch (event.key) {
        case "ArrowLeft":
          spherical.theta += step;
          break;
        case "ArrowRight":
          spherical.theta -= step;
          break;
        case "ArrowUp":
          spherical.phi -= step;
          break;
        case "ArrowDown":
          spherical.phi += step;
          break;
        case "+":
        case "=":
          spherical.radius *= 0.8;
          break;
        case "-":
        case "_":
          spherical.radius /= 0.8;
          break;
        default:
          return;
      }
      event.preventDefault();
      spherical.phi = MathUtils.clamp(spherical.phi, 0.05, controls.maxPolarAngle);
      spherical.radius = MathUtils.clamp(spherical.radius, controls.minDistance, controls.maxDistance);
      spherical.makeSafe();
      camera.position.copy(controls.target).add(new Vector3().setFromSpherical(spherical));
      camera.lookAt(controls.target);
      controls.update();
    };
    element.addEventListener("keydown", onKey);
    return () => element.removeEventListener("keydown", onKey);
  }, [target, camera, controls, onReset]);

  return null;
}

export interface ScanViewerProps {
import { useId, type ReactNode } from "react";

/**
 * An on/off switch (role="switch"). The whole row is the button, so it's a big tap
 * target, and the state is written out ("On"/"Off") as well as shown by the knob.
 */
export default function Switch({
  checked,
  onChange,
  label,
  detail,
  tone = "light",
}: {
  checked: boolean;
  onChange: (checked: boolean) => void;
  label: ReactNode;
  detail?: ReactNode;
  /** "light" for paper/surface backgrounds, "dark" for night (3D view). */
  tone?: "light" | "dark";
}) {
  const labelId = useId();
  const detailId = useId();
  const dark = tone === "dark";
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      aria-labelledby={labelId}
      aria-describedby={detail ? detailId : undefined}
      onClick={() => onChange(!checked)}
      className={`flex min-h-12 w-full items-center gap-4 rounded-xl px-4 py-3 text-left ${
        dark ? "bg-night/85 text-paper ring-1 ring-sage/40" : "bg-surface text-forest ring-1 ring-forest/15"
      }`}
    >
      <span className="min-w-0 flex-1">
        <span id={labelId} className="block font-bold">
          {label}
        </span>
        {detail ? (
        <div className="-mr-1 flex items-center gap-1">
          <Link to="/settings" aria-label="Settings" className="grid size-11 place-items-center rounded-full text-muted">
            <SettingsIcon className="size-5" aria-hidden />
          </Link>
          <span className="sr-only">Signed in as {user.name}</span>
          <Avatar initials={user.initials} className="size-8 text-sm" />
        </div>
      </header>

      <main id="main" tabIndex={-1} className="min-w-0 flex-1 px-4 pt-4 pb-28 focus:outline-none md:px-10 md:pt-10 md:pb-12">
        <Outlet />
      </main>

      <AppToaster />

      {/* Phone tab bar */}
      <nav
        aria-label="Main"
        data-surface="forest"
        className="fixed inset-x-0 bottom-0 z-10 grid grid-cols-3 bg-forest px-2 pt-2 pb-[max(0.5rem,env(safe-area-inset-bottom))] text-paper md:hidden"
      >
        <TabLink item={NAV[0]!} />
        <Link
          to="/maps/new"
          className="mx-auto -mt-6 grid size-14 place-items-center rounded-full bg-coral text-ink shadow-lg ring-4 ring-paper"
          aria-label="New map"
        >
          <Plus className="size-7" aria-hidden />
        </Link>
        <TabLink item={NAV[1]!} />
      </nav>
    </div>
  );
}

function TabLink({ item: { to, label, icon: Icon } }: { item: NavItem }) {
  return (
    <NavLink
      to={to}
      end
      className={({ isActive }) =>
        `flex min-h-12 flex-col items-center justify-center gap-0.5 text-xs font-bold ${
          isActive ? "text-paper" : "text-sage"
        }`
      }
    >
      <Icon className="size-6" aria-hidden />
      {label}
    </NavLink>
  );
}

/** First thing a keyboard user reaches: jumps past the menu to the page content. */
export function SkipLink() {
  return (
    <a
      href="#main"
      data-surface="forest"
      className="fixed top-2 left-2 z-50 -translate-y-24 rounded-full bg-forest px-5 py-3 font-bold text-paper shadow-lg focus:translate-y-0"
    >
      Skip to main content

